def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the rectangular 5-frame and its interior bounds.
    frame_rows = [r for r in range(h) if sum(v == 5 for v in grid[r]) >= 2]
    frame_cols = [c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) >= 2]
    top, bottom = min(frame_rows), max(frame_rows)
    left, right = min(frame_cols), max(frame_cols)
    rm = (top + bottom) // 2
    cm = (left + right) // 2

    # Markers outside the frame determine their corresponding corner colors;
    # each color also fills the diagonally opposite corner.
    corners = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 5:
                continue
            vertical = 0 if r < top else 1
            horizontal = 0 if c < left else 1
            corner = (vertical, horizontal)
            corners[corner] = color
            corners[(1 - vertical, 1 - horizontal)] = color

    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            corner = (0 if r <= rm else 1, 0 if c <= cm else 1)
            if corner in corners:
                out[r][c] = corners[corner]
    return out
